/*!50003 CREATE*/ /*!50017 DEFINER=`zooadmin`@`%`*/ /*!50003 TRIGGER `trg_employee_user_sync_update` AFTER UPDATE ON `employee` FOR EACH ROW BEGIN
          IF (OLD.first_name <> NEW.first_name OR OLD.last_name <> NEW.last_name OR OLD.email <> NEW.email) THEN
              UPDATE users
              SET first_name = NEW.first_name,
                  last_name  = NEW.last_name,
