/*!50003 CREATE*/ /*!50017 DEFINER=`zooadmin`@`%`*/ /*!50003 TRIGGER `trg_low_stock_alert` AFTER UPDATE ON `product` FOR EACH ROW BEGIN
        IF NEW.quantity_in_stock <= COALESCE(NEW.reorder_level, 5) AND OLD.quantity_in_stock > COALESCE(OLD.reorder_level, 5) THEN
            INSERT INTO low_stock_alert (product_ID, stock_at_alert, status)
            VALUES (NEW.product_ID, NEW.quantity_in_stock, 'unaddressed');
        END IF;
        IF NEW.quantity_in_stock > COALESCE(NEW.reorder_level, 5) THEN
            UPDATE low_stock_alert
            SET status = 'dismissed'
            WHERE product_ID = NEW.product_ID AND status != 'dismissed';
        END IF;
    END */;;
DELIMITER ;
