/*!50003 CREATE*/ /*!50017 DEFINER=`zooadmin`@`%`*/ /*!50003 TRIGGER `salary_budget_default_last` BEFORE INSERT ON `salary_budget` FOR EACH ROW BEGIN
  IF NEW.annual_salary_budget IS NULL THEN
    SET NEW.annual_salary_budget = COALESCE(
      (SELECT annual_salary_budget
       FROM salary_budget
       WHERE fiscal_year < NEW.fiscal_year
       ORDER BY fiscal_year DESC
       LIMIT 1),
      450000
    );
  END IF;
END */;;
