/*!50003 CREATE*/ /*!50017 DEFINER=`zooadmin`@`%`*/ /*!50003 TRIGGER `validate_donation_item_insert` BEFORE INSERT ON `transaction_item` FOR EACH ROW BEGIN
    IF NEW.item_type = 'donation'
        AND NOT EXISTS (
            SELECT 1
            FROM DONATION
            WHERE donation_ID = NEW.item_ID
        )
    THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Donation does not exist';
    END IF;
END */;;
